(docs/'privacy.html').write_text(head('Privacy Policy | Metronome','How Metronome handles your settings, practice information and anonymous diagnostics.','privacy.html')+f'<main id="main"><div class="document-head wrap"><a class="text-link" href="/">{icon("back")}Back to Metronome</a><p class="eyebrow">The details</p><h1>Privacy Policy</h1><p class="caption">Last updated: September 3, 2026</p></div><div class="document-content wrap">{legal}</div></main>'+footer+'</body></html>')
